import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { Icon } from '@/components/ui/Icon.js';
import { listWords } from '@/db/repo.js';
import { t } from '@/i18n/index.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { usePlanLimits } from '@/lib/useConfig.js';
import { ProMark } from '@/features/billing/ProMark.js';
import { TrialOptIn } from '@/features/billing/TrialOptIn.js';
import { offerable, useBilling } from '@/features/billing/state.js';
import { trialEligible } from '@/features/billing/trial.js';
import { exampleQuestions, type ExampleQuestion } from './lexExamples.js';
import styles from './LexLocked.module.css';

/**
 * Lex on Free (app audit 2026-10-22, owner-approved): one card on the
 * story's ground saying what Lex is, three questions the learner could ask
 * with their own words, and one honest button — the trial while it is open
 * to this account, otherwise "See Pro". Where Pro cannot be sold, nothing
 * offers it and the screen only says what Lex is.
 */
export function LexLocked({
  notebook,
  onSeePro,
}: {
  notebook: { id: string; targetLang: LanguageCode; meaningLang: LanguageCode } | undefined;
  /**
   * Opens the Pro sheet. The screen owns it, so buying (which unlocks Lex and
   * takes this card away) keeps the sheet and its "Pro is yours".
   */
  onSeePro: () => void;
}): React.JSX.Element {
  const billing = useBilling((s) => s.state);
  const limits = usePlanLimits();
  const words = useLiveQuery(async () => (notebook === undefined ? [] : listWords(notebook.id)), undefined, [
    notebook?.id,
  ]);
  const examples = exampleQuestions(words ?? []);
  const sells = offerable(billing, notebook?.targetLang, notebook?.meaningLang);
  const trial = trialEligible(billing, notebook);
  const lexDaily = limits.pro?.lexDaily;
  const see = onSeePro;

  return (
    <div className={styles.locked}>
      <section className={styles.card} aria-labelledby="lex-locked-head">
        <ProMark />
        <h2 id="lex-locked-head" className={styles.head}>
          {t('lexLocked.head')} <span className={styles.accent}>{t('lexLocked.headAccent')}</span>
        </h2>
        <p className={styles.sub}>{t('lexLocked.sub')}</p>
      </section>

      {words !== undefined &&
        (examples.length === 0 ? (
          <p className={styles.few}>{t('lexLocked.few')}</p>
        ) : (
          <section className={styles.examples} aria-labelledby="lex-examples">
            <h3 id="lex-examples" className={styles.examplesTitle}>
              {t('lexLocked.examplesTitle')}
            </h3>
            <ul className={styles.list}>
              {examples.map((example) => (
                <li key={example.key}>
                  {sells ? (
                    <button type="button" className={styles.example} onClick={see}>
                      <Icon name="sparkles" size={15} weight={2} className={styles.mark} />
                      <Question example={example} lang={notebook?.targetLang ?? 'en'} />
                    </button>
                  ) : (
                    <p className={styles.example}>
                      <Icon name="sparkles" size={15} weight={2} className={styles.mark} />
                      <Question example={example} lang={notebook?.targetLang ?? 'en'} />
                    </p>
                  )}
                </li>
              ))}
            </ul>
          </section>
        ))}

      {sells &&
        (trial ? (
          <TrialOptIn asButton rowClass={undefined} labelClass={undefined} valueClass={undefined} />
        ) : (
          <button type="button" className={styles.button} onClick={see}>
            {t('pro.see')}
          </button>
        ))}
      {sells && lexDaily !== undefined && (
        <p className={styles.limit}>{t('lexLocked.limit', { count: lexDaily })}</p>
      )}
    </div>
  );
}

/** A question's sentence with each of the learner's words in its own language. */
function Question({ example, lang }: { example: ExampleQuestion; lang: LanguageCode }): React.JSX.Element {
  const template = t(`lexLocked.q.${example.key}`);
  const parts = template.split(/(\{w[12]\})/);
  return (
    <span className={styles.question}>
      {parts.map((part, index) => {
        const slot = part === '{w1}' ? 0 : part === '{w2}' ? 1 : -1;
        if (slot === -1) return <span key={index}>{part}</span>;
        return (
          <Bilingual key={index} lang={lang} className={styles.word}>
            {example.words[slot] ?? ''}
          </Bilingual>
        );
      })}
    </span>
  );
}
