import { useRef, useState } from 'react';
import type { LanguageCode } from '@lexpad/core';
import { firstStrongDir } from './richText.js';
import { Icon } from '@/components/ui/Icon.js';
import { VoiceButton } from '@/components/ui/VoiceButton.js';
import { cx } from '@/lib/cx.js';
import { t } from '@/i18n/index.js';
import styles from './Assistant.module.css';

/** How tall the box may grow before it scrolls instead, in pixels. */
const MAX_HEIGHT = 132;

/**
 * Where a question is written or said.
 *
 * The field grows with the question up to a few lines and then scrolls: a
 * box that keeps growing pushes the answer it is about off the screen.
 *
 * Enter sends on a keyboard and adds a line on a touch screen, because a
 * phone keyboard's return key is the only way to write a second line and
 * taking it away would make longer questions impossible.
 */
export function Composer({
  lang,
  busy,
  onSend,
}: {
  /** The language the learner writes in: the notebook's meaning language. */
  lang: LanguageCode;
  busy: boolean;
  onSend: (text: string) => void;
}): React.JSX.Element {
  const [text, setText] = useState('');
  const typing = firstStrongDir(text) ?? 'ltr';
  const [problem, setProblem] = useState('');
  const box = useRef<HTMLTextAreaElement>(null);

  const resize = (el: HTMLTextAreaElement): void => {
    el.style.height = 'auto';
    el.style.height = `${Math.min(el.scrollHeight, MAX_HEIGHT)}px`;
  };

  const send = (): void => {
    const question = text.trim();
    if (question === '' || busy) return;
    onSend(question);
    setText('');
    if (box.current !== null) {
      box.current.style.height = 'auto';
      box.current.focus();
    }
  };

  return (
    // Marked so a floating toast steps out of its way (app/toastPlacement).
    <div className={styles.composer} data-keep-clear="">
      {problem !== '' && (
        <p className={styles.problem} role="status">
          {problem}
        </p>
      )}
      <div className={styles.field}>
        <textarea
          ref={box}
          className={styles.input}
          value={text}
          rows={1}
          /* Which way the box runs follows what is being typed in it, from
             the first letter that carries a direction. An empty box reads
             left to right: a box with nothing in it has no language, and
             one that opens on the right because of the notebook is a guess
             that is wrong as often as it is right. */
          dir={typing}
          lang={lang}
          placeholder={t('assistant.placeholder')}
          aria-label={t('assistant.placeholder')}
          onChange={(event) => {
            setText(event.target.value);
            resize(event.target);
          }}
          onKeyDown={(event) => {
            // A modifier is a deliberate newline; bare Enter with no touch
            // screen in sight is a send.
            if (event.key !== 'Enter' || event.shiftKey || event.altKey) return;
            if (window.matchMedia('(pointer: coarse)').matches) return;
            event.preventDefault();
            send();
          }}
        />
        <VoiceButton
          lang={lang}
          className={styles.mic}
          onProblem={setProblem}
          onHeard={(heard) => {
            setProblem('');
            // Added to what is there rather than replacing it: somebody who
            // typed half a question and then spoke the rest meant both.
            setText((current) => (current === '' ? heard : `${current} ${heard}`));
            if (box.current !== null) resize(box.current);
          }}
        />
      </div>
      <button
        type="button"
        className={cx(styles.send, (text.trim() === '' || busy) && styles.sendOff)}
        aria-label={t('assistant.send')}
        disabled={text.trim() === '' || busy}
        onClick={send}
      >
        <Icon name="arrowRight" size={20} weight={2.1} />
      </button>
    </div>
  );
}
