import { useState } from 'react';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { localTimeZone } from '@/lib/format.js';
import { cx } from '@/lib/cx.js';
import { t, type MessageKey } from '@/i18n/index.js';
import type { ApiLexAction, ApiLexActionDecision } from '@/api/types.js';
import { applyAction, checkAction, type ActionCheck, type ActionProblem } from './actions.js';
import styles from './Assistant.module.css';

/** What a card says and does, for one proposal. */
interface Wording {
  icon: IconName;
  ask: string;
  body?: string;
  button: string;
  chip: string;
  done: string;
  danger?: boolean;
}

function wordingOf(action: ApiLexAction): Wording {
  const word = action.headword;
  const v = { word };
  switch (action.tool) {
    case 'add_word':
      return action.exists === true
        ? {
            icon: 'arrowRight',
            ask: t('assistant.action.raise', v),
            button: t('assistant.action.raiseButton'),
            chip: t('assistant.action.offerAdd', v),
            done: t('assistant.action.raised', v),
          }
        : {
            icon: 'plus',
            ask: t('assistant.action.add', v),
            ...(action.meaning !== undefined && action.meaning !== '' ? { body: action.meaning } : {}),
            button: t('assistant.action.addButton'),
            chip: t('assistant.action.offerAdd', v),
            done: t('assistant.action.added', v),
          };
    case 'update_meaning':
      return {
        icon: 'pencil',
        ask:
          (action.index ?? 1) > 1
            ? t('assistant.action.meaningNth', { word, index: action.index ?? 1 })
            : t('assistant.action.meaning', v),
        body: action.meaning ?? '',
        button: t('assistant.action.meaningButton'),
        chip: t('assistant.action.offerMeaning', v),
        done: t('assistant.action.changed', v),
      };
    case 'set_starred':
      return action.value === true
        ? {
            icon: 'star',
            ask: t('assistant.action.star', v),
            button: t('assistant.action.starButton'),
            chip: t('assistant.action.offerStar', v),
            done: t('assistant.action.starred', v),
          }
        : {
            icon: 'star',
            ask: t('assistant.action.unstar', v),
            button: t('assistant.action.unstarButton'),
            chip: t('assistant.action.offerUnstar', v),
            done: t('assistant.action.unstarred', v),
          };
    case 'set_retired':
      return action.value === true
        ? {
            icon: 'pause',
            ask: t('assistant.action.retire', v),
            body: t('assistant.action.retireBody'),
            button: t('assistant.action.retireButton'),
            chip: t('assistant.action.offerRetire', v),
            done: t('assistant.action.retired', v),
          }
        : {
            icon: 'undo',
            ask: t('assistant.action.unretire', v),
            button: t('assistant.action.unretireButton'),
            chip: t('assistant.action.offerUnretire', v),
            done: t('assistant.action.unretired', v),
          };
    case 'delete_word':
      return {
        icon: 'close',
        ask: t('assistant.action.delete', v),
        button: t('assistant.action.deleteButton'),
        chip: t('assistant.action.offerDelete', v),
        done: t('assistant.action.deleted', v),
        danger: true,
      };
  }
}

const PROBLEM: Record<ActionProblem, MessageKey> = {
  viewer: 'assistant.action.viewer',
  word: 'assistant.action.gone',
  notebook: 'assistant.action.elsewhere',
};

const PENDING: ActionCheck | null = null;

/**
 * The changes an answer proposes, under it.
 *
 * A change the learner asked for is a card: what will happen, as a
 * question, with the one button that does it and "Not now". A change Lex
 * offered on its own is a chip; tapping it opens the same card. Nothing is
 * applied until the button is tapped, and a delete asks once more through
 * the app's one confirmation sheet.
 */
export function ActionCards({
  actions,
  onDecide,
}: {
  actions: readonly ApiLexAction[];
  onDecide: (actionId: string, state: ApiLexActionDecision) => void;
}): React.JSX.Element | null {
  const [opened, setOpened] = useState<string | null>(null);
  const live = actions.filter((a) => a.state !== 'dismissed');
  if (live.length === 0) return null;

  const cards = live.filter((a) => a.kind === 'request' || a.state === 'applied' || a.id === opened);
  const chips = live.filter((a) => a.kind === 'offer' && a.state === 'proposed' && a.id !== opened);

  return (
    <div className={styles.actions}>
      {cards.map((action) => (
        <ActionCard key={action.id} action={action} onDecide={onDecide} />
      ))}
      {chips.length > 0 && (
        <ul className={styles.chips} aria-label={t('assistant.action.suggestions')}>
          {chips.map((action) => {
            const wording = wordingOf(action);
            return (
              <li key={action.id}>
                <button
                  type="button"
                  className={styles.chip}
                  aria-haspopup="dialog"
                  onClick={() => {
                    setOpened(action.id);
                  }}
                >
                  <Icon name={wording.icon} size={14} weight={2} />
                  {wording.chip}
                </button>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

function ActionCard({
  action,
  onDecide,
}: {
  action: ApiLexAction;
  onDecide: (actionId: string, state: ApiLexActionDecision) => void;
}): React.JSX.Element {
  const wording = wordingOf(action);
  const [busy, setBusy] = useState(false);
  const [failed, setFailed] = useState<ActionProblem | 'failed' | null>(null);
  // Added, but its card could not be written now: it waits for Fill with AI.
  const [unfilled, setUnfilled] = useState(false);
  const [confirming, setConfirming] = useState(false);
  // Checked against this device's copy as it is now, so a word deleted on
  // another phone or a notebook shared down to view-only says so before the
  // learner taps, not after.
  const check = useLiveQuery(() => checkAction(action), PENDING, [action]);

  if (action.state === 'applied') {
    return (
      <p className={styles.actionDone} role="status">
        <Icon name="check" size={15} weight={2.2} />
        {unfilled ? t('assistant.action.addedUnfilled', { word: action.headword }) : wording.done}
      </p>
    );
  }

  const apply = (): void => {
    setBusy(true);
    setFailed(null);
    applyAction(action, localTimeZone())
      .then((outcome) => {
        setBusy(false);
        if (outcome === 'unfilled') setUnfilled(true);
        else if (outcome !== undefined) {
          setFailed(outcome);
          return;
        }
        onDecide(action.id, 'applied');
      })
      .catch(() => {
        setBusy(false);
        setFailed('failed');
      });
  };

  const problem = failed ?? (check !== null && !check.ok ? check.problem : null);
  const blocked = problem !== null && problem !== 'failed';

  return (
    <section
      className={cx(styles.actionCard, wording.danger === true && styles.actionDanger)}
      aria-label={wording.ask}
    >
      <span className={styles.actionIcon} aria-hidden="true">
        <Icon name={wording.icon} size={16} weight={2} />
      </span>
      <div className={styles.actionText}>
        <p className={styles.actionAsk}>{wording.ask}</p>
        {wording.body !== undefined && wording.body !== '' && (
          <p className={styles.actionBody} dir="auto">
            {wording.body}
          </p>
        )}
        {problem !== null && (
          <p className={styles.actionProblem} role="status">
            {problem === 'failed'
              ? t('assistant.action.failed')
              : t(PROBLEM[problem], { word: action.headword })}
          </p>
        )}
        <div className={styles.actionButtons}>
          {!blocked && (
            <Button
              size="small"
              variant={wording.danger === true ? 'danger' : 'primary'}
              busy={busy}
              disabled={check === null}
              onClick={() => {
                if (action.tool === 'delete_word') setConfirming(true);
                else apply();
              }}
            >
              {wording.button}
            </Button>
          )}
          <Button
            size="small"
            variant="ghost"
            disabled={busy}
            onClick={() => {
              onDecide(action.id, 'dismissed');
            }}
          >
            {blocked ? t('assistant.action.dismiss') : t('assistant.action.notNow')}
          </Button>
        </div>
      </div>
      {/* Deleting takes the word's progress with it and cannot be undone,
          so it asks once more, in the one sheet that asks anything. */}
      {confirming && (
        <Confirm
          title={t('word.removeTitle', { word: action.headword })}
          body={t('word.removeBody')}
          confirmLabel={t('assistant.action.deleteButton')}
          danger
          onCancel={() => {
            setConfirming(false);
          }}
          onConfirm={() => {
            setConfirming(false);
            apply();
          }}
        />
      )}
    </section>
  );
}
