import { useCallback, useEffect, useRef, useState } from 'react';
import { lex } from '@/api/endpoints.js';
import { ApiError } from '@/api/errors.js';
import { t } from '@/i18n/index.js';
import type { ApiLexActionDecision, ApiLexConversation, ApiLexFeedback, ApiLexMessage } from '@/api/types.js';

/**
 * The chat, as a small state machine.
 *
 * Two things shape it. An answer is written by the server whether or not
 * anybody is listening, so the screen never owns the answer — it follows
 * one. And the stream can be joined late, twice, or again after the phone
 * was locked, so every path through here ends in the same place: read the
 * message rows, then follow any that is still being written.
 */

/** A message as the screen holds it, which is the API's plus what is local. */
export interface ChatMessage extends ApiLexMessage {
  /** True while tokens are still arriving into this one. */
  live?: boolean;
}

export type ChatPhase =
  | { kind: 'loading' }
  | { kind: 'ready' }
  | { kind: 'failed'; message: string }
  /** Nobody has a notebook yet, so there is nothing to talk about. */
  | { kind: 'nothing' };

export interface LexChat {
  phase: ChatPhase;
  conversation: ApiLexConversation | null;
  messages: ChatMessage[];
  /** True between sending a question and the first token of its answer. */
  thinking: boolean;
  ask: (text: string) => void;
  regenerate: (answerId: string) => void;
  rate: (answerId: string, feedback: ApiLexFeedback) => void;
  unrate: (answerId: string) => void;
  /**
   * Records what the learner did with a change Lex proposed. The change
   * itself was already made on this device (or not, for "Not now"); this
   * shows the decision at once and tells the server, so the card does not
   * come back.
   */
  decide: (answerId: string, actionId: string, state: ApiLexActionDecision) => void;
  /** Opens a thread that already exists, from the history list. */
  open: (id: string) => void;
  /** Leaves the current thread and starts a new one on the next question. */
  reset: () => void;
  remove: (id: string) => Promise<void>;
  retry: () => void;
}

/**
 * What a failure says, always in the app's own words (app audit
 * 2026-10-22): a server's raw message ("unmocked endpoint …", a stack
 * line) never reaches the screen. Offline says so and that the notebook
 * still works; the one refusal the server words for a learner (an address
 * not confirmed yet) keeps its words.
 */
function messageOf(error: unknown, fallback: string, offline: string = t('assistant.offline')): string {
  if (!(error instanceof ApiError)) return fallback;
  if (error.kind === 'offline') return offline;
  if (error.kind === 'tooMany') return t('assistant.resting');
  if (error.code === 'email_unverified') return error.message;
  return fallback;
}

export function useLexChat(
  notebookId: string | undefined,
  strings: { offline: string; failed: string },
): LexChat {
  const [phase, setPhase] = useState<ChatPhase>({ kind: 'loading' });
  const [conversation, setConversation] = useState<ApiLexConversation | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [thinking, setThinking] = useState(false);
  // One stream at a time, and it is cancelled when the screen goes away:
  // the answer keeps being written, this just stops reading it.
  const listening = useRef<AbortController | null>(null);
  const alive = useRef(true);
  // The copy the async paths read, kept fresh in an effect rather than
  // during render: a ref written while rendering is a ref two renders can
  // disagree about.
  const text = useRef(strings);
  useEffect(() => {
    text.current = strings;
  }, [strings]);

  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
      listening.current?.abort();
    };
  }, []);

  /**
   * Follows one answer to its end, appending tokens as they arrive.
   *
   * `after` is the last event id already rendered, so a stream rejoined
   * after a drop sends only what was missed rather than repeating an answer
   * the reader has already watched appear.
   */
  const follow = useCallback((answerId: string, after?: string) => {
    listening.current?.abort();
    const controller = new AbortController();
    listening.current = controller;
    let seen = after ?? '';

    const stop = (patch: Partial<ChatMessage>): void => {
      if (!alive.current) return;
      setThinking(false);
      setMessages((all) => all.map((m) => (m.id === answerId ? { ...m, ...patch, live: false } : m)));
    };

    void lex
      .listen(
        answerId,
        {
          onToken: (token, id) => {
            if (!alive.current) return;
            seen = id;
            setThinking(false);
            setMessages((all) =>
              all.map((m) => (m.id === answerId ? { ...m, text: m.text + token, live: true } : m)),
            );
          },
          onActions: (actions) => {
            if (!alive.current) return;
            setMessages((all) => all.map((m) => (m.id === answerId ? { ...m, actions } : m)));
          },
          onDone: () => {
            stop({ status: 'complete' });
          },
          onError: (reason) => {
            stop({ status: 'failed', error: reason });
          },
        },
        { ...(seen !== '' ? { after: seen } : {}), signal: controller.signal },
      )
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        // The answer is still being written on the server; only the reading
        // stopped. Say the connection went rather than that Lex failed.
        stop({ status: 'failed', error: messageOf(error, text.current.offline, text.current.offline) });
      });
  }, []);

  /** Puts a thread and its messages on screen, resuming a live answer. */
  const show = useCallback(
    (full: { conversation: ApiLexConversation; messages: ApiLexMessage[] }) => {
      setConversation(full.conversation);
      setMessages(full.messages);
      setPhase({ kind: 'ready' });
      // An answer left half-written — the phone was locked, the tab was
      // closed — is picked up from where it got to, not from the beginning.
      const last = full.messages[full.messages.length - 1];
      if (last?.role === 'assistant' && last.status === 'streaming') {
        setThinking(last.text === '');
        follow(last.id);
      }
    },
    [follow],
  );

  // A promise chain rather than an awaited async body, so every setState
  // below happens in a callback: the mount effect starts a fetch and
  // nothing else, which is the shape the rest of this app uses.
  const load = useCallback(
    () =>
      lex
        .conversations(undefined, 1)
        .then((page) => {
          const latest = page.items[0];
          if (latest === undefined) {
            if (alive.current) {
              setConversation(null);
              setMessages([]);
              setPhase({ kind: 'ready' });
            }
            return undefined;
          }
          return lex.conversation(latest.id).then((full) => {
            if (alive.current) show(full);
            return undefined;
          });
        })
        .catch((error: unknown) => {
          if (alive.current) setPhase({ kind: 'failed', message: messageOf(error, text.current.failed) });
        }),
    [show],
  );

  useEffect(() => {
    void load();
  }, [load]);

  const ask = useCallback(
    (question: string) => {
      const body = question.trim();
      if (body === '') return;
      setThinking(true);
      void (async () => {
        try {
          let thread = conversation;
          if (thread === null) {
            thread = await lex.start(notebookId);
            if (!alive.current) return;
            setConversation(thread);
          }
          const { question: asked, answer } = await lex.ask(thread.id, body);
          if (!alive.current) return;
          setMessages((all) => [...all, asked, { ...answer, live: true }]);
          follow(answer.id);
        } catch (error) {
          if (!alive.current) return;
          setThinking(false);
          setPhase({ kind: 'failed', message: messageOf(error, text.current.failed) });
        }
      })();
    },
    [conversation, follow, notebookId],
  );

  const regenerate = useCallback(
    (answerId: string) => {
      setThinking(true);
      void (async () => {
        try {
          const answer = await lex.regenerate(answerId);
          if (!alive.current) return;
          // Appended rather than swapped in: the first answer really was
          // given, and a conversation that quietly rewrites its own history
          // is one nobody can check.
          setMessages((all) => [...all, { ...answer, live: true }]);
          follow(answer.id);
        } catch (error) {
          if (!alive.current) return;
          setThinking(false);
          setPhase({ kind: 'failed', message: messageOf(error, text.current.failed) });
        }
      })();
    },
    [follow],
  );

  const rate = useCallback((answerId: string, feedback: ApiLexFeedback) => {
    // Shown as given at once. A rating is the reader's own opinion, so
    // making them wait for a round trip to see it registered is a delay
    // that buys nothing; a failure puts it back.
    setMessages((all) => all.map((m) => (m.id === answerId ? { ...m, feedback } : m)));
    void lex.rate(answerId, feedback).catch(() => {
      if (!alive.current) return;
      setMessages((all) =>
        all.map((m) => {
          if (m.id !== answerId) return m;
          const { feedback: _dropped, ...rest } = m;
          return rest;
        }),
      );
    });
  }, []);

  const unrate = useCallback((answerId: string) => {
    setMessages((all) =>
      all.map((m) => {
        if (m.id !== answerId) return m;
        const { feedback: _dropped, ...rest } = m;
        return rest;
      }),
    );
    // A rating that will not clear is not worth telling anybody about: the
    // sweep of unrated answers is the same either way.
    void lex.unrate(answerId).catch(() => undefined);
  }, []);

  const decide = useCallback((answerId: string, actionId: string, state: ApiLexActionDecision) => {
    setMessages((all) =>
      all.map((m) =>
        m.id === answerId && m.actions !== undefined
          ? { ...m, actions: m.actions.map((a) => (a.id === actionId ? { ...a, state } : a)) }
          : m,
      ),
    );
    // Not put back on failure: an applied change has already happened here,
    // and a dismissed card the learner closed should stay closed. The
    // worst a lost decision does is show the card again in a reopened chat,
    // where applying it a second time changes nothing or says the word is
    // gone.
    void lex.decide(answerId, actionId, state).catch(() => undefined);
  }, []);

  const open = useCallback(
    (id: string) => {
      listening.current?.abort();
      setPhase({ kind: 'loading' });
      lex
        .conversation(id)
        .then((full) => {
          if (alive.current) show(full);
        })
        .catch((error: unknown) => {
          if (alive.current) setPhase({ kind: 'failed', message: messageOf(error, text.current.failed) });
        });
    },
    [show],
  );

  const reset = useCallback(() => {
    listening.current?.abort();
    setConversation(null);
    setMessages([]);
    setThinking(false);
    setPhase({ kind: 'ready' });
  }, []);

  const remove = useCallback(
    async (id: string) => {
      await lex.remove(id);
      if (!alive.current) return;
      if (conversation?.id === id) reset();
    },
    [conversation, reset],
  );

  return {
    phase,
    conversation,
    messages,
    thinking,
    ask,
    regenerate,
    rate,
    unrate,
    decide,
    open,
    reset,
    remove,
    retry: () => {
      setPhase({ kind: 'loading' });
      void load();
    },
  };
}
