/**
 * Changes Lex proposes, applied on this device.
 *
 * The server never makes a change Lex suggests. It sends a proposal; the
 * learner taps it; this applies it through the same mutations every other
 * screen uses, so the word is written locally and queued for sync in one
 * transaction, offline or not. Nothing here runs without that tap.
 *
 * The server already checked the proposal. It is checked again here against
 * what this device holds, because the notebook may have changed since the
 * answer was written (the word deleted on another phone, the notebook
 * shared down to view-only), and because what a model wrote is never
 * trusted twice on one check.
 *
 * A word Lex adds gets a whole card, as complete as Fill with AI writes
 * (owner, 20 Oct 2026): every sense with its gloss and examples, part of
 * speech, level, pronunciation, collocations, expressions, related words
 * and notes. The card is the normal AI fill, through the same job endpoint,
 * shared cache and allowance as Fill with AI, so it costs what filling the
 * word by hand would and is reportable like any card the model wrote. The
 * one-line meaning in Lex's answer is only the preview on the card: when
 * the fill cannot run (offline, the day's AI used up, a failed job) the
 * word is saved with no meaning, which is how a word waiting for Fill with
 * AI is marked, and the learner is told. Never a half card in silence.
 */
import { normalizeHeadword } from '@lexpad/core';
import type { ApiLexAction } from '@/api/types.js';
import { db, type LexpadDb, type StoredNotebook, type StoredWord } from '@/db/schema.js';
import {
  addWord,
  editWord,
  enrichWord,
  findByHeadword,
  removeWord,
  setProgressFlags,
} from '@/db/mutations.js';
import { aiPausedUntil } from '@/features/ai/quota.js';
import { generateCardWithJob, type GeneratedCard } from '@/features/ai/generate.js';
import { syncSoon } from '@/sync/store.js';

/** Why a proposal cannot be applied here. */
export type ActionProblem =
  /** The notebook is not on this device, or not the one the chat is about. */
  | 'notebook'
  /** The learner may only read this notebook. */
  | 'viewer'
  /** The word is not in the notebook any more, or is not the one named. */
  | 'word';

export type ActionCheck =
  { ok: true; notebook: StoredNotebook; word?: StoredWord } | { ok: false; problem: ActionProblem };

/** The tools a card knows how to apply. Anything else is never applied. */
const TOOLS = new Set<ApiLexAction['tool']>([
  'add_word',
  'update_meaning',
  'set_starred',
  'set_retired',
  'delete_word',
]);

/** Whether a proposal can be applied to what this device holds. */
export async function checkAction(action: ApiLexAction, database: LexpadDb = db): Promise<ActionCheck> {
  if (!TOOLS.has(action.tool)) return { ok: false, problem: 'word' };
  const notebook = await database.notebooks.get(action.notebookId);
  if (notebook === undefined) return { ok: false, problem: 'notebook' };
  if (notebook.role === 'viewer') return { ok: false, problem: 'viewer' };

  const named = normalizeHeadword(action.headword);
  if (named === '') return { ok: false, problem: 'word' };
  // The id the server resolved, when there is one, and the headword as a
  // fallback for a word this device created before it synced. Either way it
  // must be in this notebook and carry the headword the card shows.
  const byId = action.wordId !== undefined ? await database.words.get(action.wordId) : undefined;
  const word = byId ?? (await findByHeadword(database, action.notebookId, action.headword));
  const matches = word?.notebookId === action.notebookId && normalizeHeadword(word.headword) === named;

  if (action.tool === 'add_word') {
    return matches ? { ok: true, notebook, word } : { ok: true, notebook };
  }
  if (!matches) return { ok: false, problem: 'word' };
  if (action.tool === 'update_meaning') {
    const index = action.index ?? 1;
    const count = word.meanings?.length ?? 0;
    if ((action.meaning ?? '').trim() === '' || index < 1 || index > Math.max(1, count)) {
      return { ok: false, problem: 'word' };
    }
  }
  if ((action.tool === 'set_starred' || action.tool === 'set_retired') && typeof action.value !== 'boolean') {
    return { ok: false, problem: 'word' };
  }
  return { ok: true, notebook, word };
}

/**
 * What applying a proposal came to: undefined when it was done in full,
 * `unfilled` when a word was added but its card could not be written yet
 * (it waits for Fill with AI), or the problem that stopped it.
 */
export type ApplyOutcome = ActionProblem | 'unfilled' | undefined;

/** Writes one word's card; the AI fill, or a stand-in in tests. */
export type CardWriter = (notebookId: string, headword: string) => Promise<GeneratedCard>;

/** The normal AI fill for one entry: no hint, so the shared cache serves it. */
const fillCard: CardWriter = (notebookId, headword) => generateCardWithJob(notebookId, headword);

/**
 * Pours the AI card into a word Lex added, adding only what the word lacks,
 * and records the job, as Fill with AI does. A topic the model chose
 * replaces the default one. Reports whether the word now has a meaning.
 */
async function completeCard(
  notebookId: string,
  wordId: string,
  headword: string,
  writeCard: CardWriter,
  database: LexpadDb,
): Promise<boolean> {
  // Resting since an earlier refusal: asking again would only be refused.
  if ((await aiPausedUntil()) !== undefined) return false;
  let generated: GeneratedCard;
  try {
    generated = await writeCard(notebookId, headword);
  } catch {
    return false;
  }
  const { card, jobId } = generated;
  await enrichWord(wordId, card, database, jobId);
  const stored = await database.words.get(wordId);
  const topic = card.category?.trim() ?? '';
  if (stored?.category === 'general' && topic !== '' && topic !== 'general') {
    await editWord(wordId, { category: topic }, database);
  }
  void syncSoon();
  return (stored?.meanings ?? []).some((sense) => sense.meaning.trim() !== '');
}

/**
 * Applies a proposal the learner tapped. Returns the problem when it cannot
 * be applied, and writes nothing then.
 */
export async function applyAction(
  action: ApiLexAction,
  timeZone: string,
  database: LexpadDb = db,
  writeCard: CardWriter = fillCard,
): Promise<ApplyOutcome> {
  const check = await checkAction(action, database);
  if (!check.ok) return check.problem;
  const { word } = check;

  switch (action.tool) {
    case 'add_word': {
      // Saved first, with the headword alone, so the word is the learner's
      // whatever happens to the fill: a closed tab or a dropped network
      // leaves a word waiting for its meaning, which Fill with AI finishes.
      // A headword the notebook already has is raised to the top instead.
      const id = await addWord(
        action.notebookId,
        { headword: action.headword, meaning: '', source: 'assistant' },
        timeZone,
        database,
      );
      // A word already in the notebook with a meaning keeps its own card:
      // raising it costs nothing, and the model would only repeat it.
      if (word !== undefined && (word.meanings ?? []).some((sense) => sense.meaning.trim() !== '')) {
        return undefined;
      }
      const written = await completeCard(action.notebookId, id, action.headword, writeCard, database);
      return written ? undefined : 'unfilled';
    }
    case 'update_meaning': {
      if (word === undefined) return 'word';
      const meanings = [...(word.meanings ?? [])];
      const at = (action.index ?? 1) - 1;
      const text = (action.meaning ?? '').trim();
      const current = meanings[at];
      // The sense keeps its examples and gloss; only its words change.
      if (current !== undefined) meanings[at] = { ...current, meaning: text };
      else meanings.push({ meaning: text });
      await editWord(word.id, { meanings }, database);
      return undefined;
    }
    case 'set_starred':
      if (word === undefined) return 'word';
      await setProgressFlags(word.id, { starred: action.value === true }, timeZone, new Date(), database);
      return undefined;
    case 'set_retired':
      if (word === undefined) return 'word';
      await setProgressFlags(word.id, { retired: action.value === true }, timeZone, new Date(), database);
      return undefined;
    case 'delete_word':
      if (word === undefined) return 'word';
      await removeWord(word.id, database);
      return undefined;
  }
}
