import styles from './Assistant.module.css';
import { blocksOf, dirOf } from './richText.js';

/**
 * The little of Markdown a language model actually writes, turned into
 * elements.
 *
 * Lex is not told to avoid Markdown, and no model obeys such an instruction
 * for long anyway: it emits bold, italics, dashes and numbered lists because
 * that is how it was taught to explain things. Rendering the answer as plain
 * text put literal asterisks on the screen and made lists run together — the
 * answer looked broken before anybody read a word of it.
 *
 * This is deliberately small rather than a Markdown library. It covers
 * paragraphs, bullet and numbered lists, bold, italics and inline code, and
 * anything it does not recognise is left exactly as written. It builds
 * elements, never HTML, so there is nothing for a model's output to inject.
 *
 * It also has to survive half an answer: while tokens arrive the text ends
 * mid-word and mid-marker, so an unclosed `**` stays literal until its
 * partner turns up rather than swallowing the rest of the paragraph.
 */

/** `**bold**`, `*italic*`, `_italic_` and `` `code` ``, nested one deep. */
const INLINE = /(\*\*[^*\n]+\*\*|\*[^*\n]+\*|_[^_\n]+_|`[^`\n]+`)/g;

function inline(text: string, keyPrefix: string): React.ReactNode[] {
  const out: React.ReactNode[] = [];
  let index = 0;
  for (const piece of text.split(INLINE)) {
    if (piece === '') continue;
    const key = `${keyPrefix}-${index++}`;
    if (piece.startsWith('**') && piece.endsWith('**') && piece.length > 4) {
      out.push(<strong key={key}>{piece.slice(2, -2)}</strong>);
    } else if (piece.startsWith('`') && piece.endsWith('`') && piece.length > 2) {
      out.push(
        <code key={key} className={styles.code}>
          {piece.slice(1, -1)}
        </code>,
      );
    } else if (
      ((piece.startsWith('*') && piece.endsWith('*')) || (piece.startsWith('_') && piece.endsWith('_'))) &&
      piece.length > 2
    ) {
      out.push(<em key={key}>{piece.slice(1, -1)}</em>);
    } else {
      out.push(piece);
    }
  }
  return out;
}

/**
 * The answer, as elements.
 *
 * Every block gets its own direction from its own words, not from the
 * notebook: Lex writes in the language it was written to, so an English
 * answer inside a Persian notebook must not be laid out right to left.
 * Taking the direction from the notebook put the full stop at the wrong end
 * of every English sentence.
 */
export function Rich({ text }: { text: string }): React.JSX.Element {
  return (
    <>
      {blocksOf(text).map((block, i) =>
        block.kind === 'p' ? (
          <p key={`b${i}`} className={styles.para} dir={dirOf(block.text)}>
            {inline(block.text, `b${i}`)}
          </p>
        ) : block.ordered ? (
          <ol key={`b${i}`} className={styles.list} dir={dirOf(block.items.join(' '))}>
            {block.items.map((item, j) => (
              <li key={`b${i}-${j}`} dir={dirOf(item)}>
                {inline(item, `b${i}-${j}`)}
              </li>
            ))}
          </ol>
        ) : (
          <ul key={`b${i}`} className={styles.list} dir={dirOf(block.items.join(' '))}>
            {block.items.map((item, j) => (
              <li key={`b${i}-${j}`} dir={dirOf(item)}>
                {inline(item, `b${i}-${j}`)}
              </li>
            ))}
          </ul>
        ),
      )}
    </>
  );
}
