import { newestFirst, type Word } from '@lexpad/core';

/**
 * The longest headword an example question uses: a phrase that would not fit
 * on two lines of a card makes the example unreadable. A layout choice.
 */
const EXAMPLE_WORD_MAX = 24;

/** The example questions, built only from words the learner saved. */
export interface ExampleQuestion {
  key: 'compare' | 'quiz' | 'sentence';
  words: string[];
}

/**
 * Up to three questions a learner could ask Lex, each filled only with
 * headwords from their own notebook (newest first, distinct, short enough to
 * read). Nothing is suggested or generated: with fewer than two words there
 * are no examples at all.
 */
export function exampleQuestions(words: readonly Word[]): ExampleQuestion[] {
  const seen = new Set<string>();
  const heads: string[] = [];
  for (const word of [...words].sort(newestFirst)) {
    const head = word.headword.trim();
    const key = head.toLowerCase();
    if (head === '' || [...head].length > EXAMPLE_WORD_MAX || seen.has(key)) continue;
    seen.add(key);
    heads.push(head);
    if (heads.length === 5) break;
  }
  const [a, b, c, d, e] = heads;
  if (a === undefined || b === undefined) return [];
  const out: ExampleQuestion[] = [{ key: 'compare', words: [a, b] }];
  if (c !== undefined && d !== undefined) out.push({ key: 'quiz', words: [c, d] });
  out.push({ key: 'sentence', words: [e ?? c ?? a] });
  return out;
}
