import { useEffect, useMemo, useRef, useState } from 'react';
import type { LanguageCode } from '@lexpad/core';
import { Button } from '@/components/ui/Button.js';
import { Confirm } from '@/components/ui/Confirm.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { Spinner } from '@/components/ui/Spinner.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { inView } from '@/db/repo.js';
import { lex } from '@/api/endpoints.js';
import { LexLocked } from './LexLocked.js';
import { Upgrade } from '@/features/billing/Upgrade.js';
import { proHere, useBilling } from '@/features/billing/state.js';
import type { ApiLexConversation } from '@/api/types.js';
import { t } from '@/i18n/index.js';
import { Bubble } from './Bubble.js';
import { Composer } from './Composer.js';
import { useLexChat } from './useLexChat.js';
import styles from './Assistant.module.css';
import { TrialProMark } from '@/features/billing/ProMark.js';

/** Questions worth a first tap, phrased as a learner would ask them. */
const OPENERS = ['assistant.opener.quiz', 'assistant.opener.confusing', 'assistant.opener.sentence'] as const;

const NO_NOTEBOOK: Awaited<ReturnType<typeof inView>> = { showing: undefined, notebooks: [], all: false };

/**
 * Lex: the assistant a learner asks about the words they wrote down.
 *
 * It talks about their notebook and nothing else — Lexpad never chooses
 * vocabulary for anybody, so Lex explains, compares and tests what is
 * already there rather than handing out lists to learn.
 *
 * The screen never owns an answer, it follows one. The server writes the
 * answer whether or not anybody is reading, so locking the phone loses
 * nothing and coming back picks up where the reading stopped.
 */
export function Assistant(): React.JSX.Element {
  const view = useLiveQuery(() => inView(), NO_NOTEBOOK, []);
  const notebook = view.showing;
  // Lex answers in the language the learner understands, so that is the
  // language of the reading, the speaking and the microphone.
  const lang: LanguageCode = notebook?.meaningLang ?? 'en';

  const strings = useMemo(
    () => ({ offline: t('assistant.connectionLost'), failed: t('assistant.loadFailed') }),
    [],
  );
  const chat = useLexChat(notebook?.id, strings);

  const [history, setHistory] = useState<ApiLexConversation[] | null>(null);
  // The Pro sheet opened from Lex on Free, held by the screen so a purchase
  // that unlocks Lex keeps it on screen to say so.
  const [proSheet, setProSheet] = useState(false);
  const [deleting, setDeleting] = useState<ApiLexConversation | null>(null);
  const thread = useRef<HTMLDivElement>(null);
  // Whether the reader is at the bottom. An answer that arrives while
  // somebody has scrolled up to re-read must not drag them away from what
  // they went back for.
  const following = useRef(true);

  // Follows the newest words down. The thread is scrolled directly rather
  // than through scrollIntoView on a sentinel: the sentinel is a zero-height
  // flex child and the browser reckons it already in view, so the thread
  // stayed exactly where the question was sent and the answer wrote itself
  // off the bottom of the screen.
  const count = chat.messages.length;
  const last = chat.messages[count - 1];
  const growing = last?.text.length ?? 0;
  useEffect(() => {
    const box = thread.current;
    if (box === null || !following.current) return;
    // Instant, not smooth: a smooth scroll restarted on every token never
    // arrives, and the reader chases the text down the screen.
    box.scrollTop = box.scrollHeight;
  }, [count, growing, chat.thinking]);

  const openHistory = (): void => {
    setHistory([]);
    void lex
      .conversations(undefined, 30)
      .then((page) => {
        setHistory(page.items);
      })
      .catch(() => {
        setHistory([]);
      });
  };

  const empty = chat.messages.length === 0;

  // Lex is Pro, and the notebook is the other way in: the server exempts a
  // notebook in a language on its free list from every paid feature, so
  // asking only about the plan would lock somebody out of something the
  // API would have given them. An unreadable plan counts as open; the
  // server is the refusal that counts.
  const billing = useBilling((s) => s.state);
  const ensure = useBilling((s) => s.ensure);
  useEffect(() => {
    ensure();
  }, [ensure]);
  const open = proHere(billing, notebook?.targetLang, notebook?.meaningLang);

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        {/* Nothing to open or start while Lex is locked: the slots stay, so the name stays centred. */}
        {open ? (
          <button
            type="button"
            className={styles.headTool}
            aria-label={t('assistant.history')}
            onClick={openHistory}
          >
            <Icon name="list" size={18} weight={1.9} />
          </button>
        ) : (
          <span />
        )}
        <h1 className={styles.title}>
          {t('assistant.title')} <TrialProMark tip />
        </h1>
        {open ? (
          <button
            type="button"
            className={styles.headTool}
            aria-label={t('assistant.newChat')}
            onClick={chat.reset}
            disabled={empty}
          >
            <Icon name="plus" size={18} weight={1.9} />
          </button>
        ) : (
          <span />
        )}
      </header>

      <div
        className={styles.thread}
        ref={thread}
        onScroll={(event) => {
          const box = event.currentTarget;
          // A few pixels of slack: a fractional scroll height means an
          // exact comparison is never true on a real device.
          following.current = box.scrollHeight - box.scrollTop - box.clientHeight < 40;
        }}
      >
        {!open && (
          <LexLocked
            notebook={notebook}
            onSeePro={() => {
              setProSheet(true);
            }}
          />
        )}

        {open && chat.phase.kind === 'loading' && (
          <div className={styles.middle}>
            <Spinner />
          </div>
        )}

        {open && chat.phase.kind === 'failed' && (
          <EmptyState
            middle
            icon="sparkles"
            tone="quiet"
            title={t('assistant.loadFailedTitle')}
            body={chat.phase.message}
            actions={<Button onClick={chat.retry}>{t('action.retry')}</Button>}
          />
        )}

        {open && chat.phase.kind === 'ready' && empty && (
          <div className={styles.welcome}>
            <span className={styles.spark} aria-hidden="true">
              <Icon name="sparkles" size={26} weight={1.7} />
            </span>
            <h2 className={styles.welcomeTitle}>{t('assistant.welcomeTitle')}</h2>
            <p className={styles.welcomeBody}>{t('assistant.welcomeBody')}</p>
            <ul className={styles.openers}>
              {OPENERS.map((key) => (
                <li key={key}>
                  <button
                    type="button"
                    className={styles.opener}
                    onClick={() => {
                      chat.ask(t(key));
                    }}
                  >
                    {t(key)}
                  </button>
                </li>
              ))}
            </ul>
          </div>
        )}

        {open && chat.phase.kind === 'ready' && !empty && <div className={styles.grow} />}

        {open &&
          chat.phase.kind === 'ready' &&
          chat.messages.map((message) => (
            <Bubble
              key={message.id}
              message={message}
              lang={lang}
              onRegenerate={() => {
                chat.regenerate(message.id);
              }}
              onRate={(verdict, reason) => {
                chat.rate(message.id, { verdict, ...(reason !== undefined ? { reason } : {}) });
              }}
              onUnrate={() => {
                chat.unrate(message.id);
              }}
              onDecide={(actionId, state) => {
                chat.decide(message.id, actionId, state);
              }}
            />
          ))}

        {/* The wait, said plainly. Three dots and nothing else would leave
            somebody wondering whether the tap registered. */}
        {open && chat.thinking && (
          <div className={styles.thinking} role="status">
            <span className={styles.dots} aria-hidden="true">
              <i />
              <i />
              <i />
            </span>
            <span className={styles.thinkingWord}>{t('assistant.thinking')}</span>
          </div>
        )}
      </div>

      {open && <Composer lang={lang} busy={chat.thinking} onSend={chat.ask} />}

      {proSheet && (
        <Upgrade
          occasion="lex"
          onClose={() => {
            setProSheet(false);
          }}
        />
      )}

      {history !== null && (
        <Sheet
          title={t('assistant.history')}
          onClose={() => {
            setHistory(null);
          }}
        >
          {history.length === 0 ? (
            <p className={styles.whyLead}>{t('assistant.noHistory')}</p>
          ) : (
            <ul className={styles.threads}>
              {history.map((one) => (
                <li key={one.id} className={styles.threadRow}>
                  <button
                    type="button"
                    className={styles.threadOpen}
                    onClick={() => {
                      chat.open(one.id);
                      setHistory(null);
                    }}
                  >
                    {one.title !== '' ? one.title : t('assistant.untitled')}
                  </button>
                  <button
                    type="button"
                    className={styles.threadDelete}
                    aria-label={t('assistant.deleteChat')}
                    onClick={() => {
                      setDeleting(one);
                    }}
                  >
                    <Icon name="close" size={16} weight={1.9} />
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Sheet>
      )}

      {/* A deleted chat does not come back, so it asks first, through the
          one sheet in the app that asks anything. */}
      {deleting !== null && (
        <Confirm
          title={t('assistant.deleteTitle')}
          body={t('assistant.deleteBody')}
          confirmLabel={t('assistant.deleteChat')}
          danger
          onCancel={() => {
            setDeleting(null);
          }}
          onConfirm={() => {
            const going = deleting;
            setDeleting(null);
            setHistory((all) => (all ?? []).filter((row) => row.id !== going.id));
            void chat.remove(going.id);
          }}
        />
      )}
    </main>
  );
}
